const HORA_FIN = 19;
const DIAS_LABORABLES = [1, 2, 3, 4, 5]; // lunes a viernes
const DURACION_MIN = parseInt($('Buscar Cita Original').first().json.duracion_minutos, 10) || 60;
const MAX_HUECOS = 5;
const VENTANA_DIAS = 7;

const citaOriginal = $('Buscar Cita Original').first().json;
const datos = $('Extraer Respuesta1').first().json;

// Eventos ocupados desde Calendar
const ocupados = $input.all()
  .filter(e => e.json && e.json.start)
  .filter(e => !(e.json.summary || '').startsWith('❌ CANCELADA'))
  .map(e => ({
    start: new Date(e.json.start.dateTime || e.json.start.date),
    end: new Date(e.json.end.dateTime || e.json.end.date)
  }));

function solapa(a, b) { return a.start < b.end && b.start < a.end; }

