const huecos = [];
let cursor = new Date(ahora);
cursor.setMinutes(Math.ceil(cursor.getMinutes() / 30) * 30, 0, 0);

while (huecos.length < MAX_HUECOS && cursor < fin) {
  const dia = cursor.getDay();
  const hora = cursor.getHours();
  const finSlotHora = new Date(cursor.getTime() + DURACION_MIN * 60000).getHours();
