const crypto = require('crypto');

const authToken = $env.TWILIO_AUTH_TOKEN;
const headers = $('Webhook Respuestas').first().json.headers;
const twilioSignature = headers['x-twilio-signature'];
const url = 'https://REEMPLAZAR_TU_DOMINIO_N8N/webhook/whatsapp-respuesta';
const params = $('Webhook Respuestas').first().json.body;

const sortedKeys = Object.keys(params).sort();
let dataString = url;
for (const key of sortedKeys) {
  dataString += key + params[key];
}

const expectedSignature = crypto.createHmac('sha1', authToken).update(Buffer.from(dataString, 'utf-8')).digest('base64');

if (expectedSignature !== twilioSignature) {
  throw new Error('Firma de Twilio inválida - petición rechazada');
}

return $input.all();

